# app.R: Shiny-App w03_voraussetzungen, Woche 3 (Voraussetzungen der multiplen Regression)
#
# Zwei verletzte Voraussetzungen des linearen Modells: ungleiche Streuung im
# Reiter „Ungleiche Streuung“ und eine nicht modellierte Krümmung im Reiter
# „Krümmung“. Spezifikation in 00_Kanon/PLAN_W03.md, Abschnitt 6, die Aufträge
# und die erwarteten Antworten in Abschnitt 4 (Folie „Aufträge“ und Leitfaden).
# Die App verwendet nur base R, shiny und ggplot2. Sie läuft lokal mit
# shiny::runApp() und im Browser als shinylive-Export (TECHNIK.md §5, Export mit
# ../export_apps.R).
#
# Datengenerierende Prozesse, je n = 250:
#   Ungleiche Streuung (wie der Datensatz therapie, bei k = 0,45 derselbe Prozess):
#     therapy_sessions = min(20; NegBin(size = 2; mu = 6))
#     symptom_drop     = 3 + 1,1 * therapy_sessions + N(0; 2 + k * therapy_sessions)
#   Krümmung (wie der Datensatz cafe, bei b = 6 und c = -0,62 derselbe Prozess):
#     noise_level ~ Uniform(0; 10)
#     creativity  = 20 + b * noise_level + c * noise_level^2 + N(0; 3)
#
# Die Regler rechnen dieselbe Stichprobe um. Neue Zufallszahlen zieht erst der
# Knopf „Eine neue Stichprobe“. Die erste Stichprobe nach dem Laden ist bei
# allen gleich: Im Reiter „Ungleiche Streuung“ entsteht sie mit dem Startwert
# 204 des Datensatzes therapie und ist bei k = 0,45 genau dieser Datensatz vor
# dem Runden (Steigung 1,08, Standardfehler 0,068). Im Reiter „Krümmung“
# entsteht sie mit dem Startwert 2040 des Datensatzes cafe und ist bei b = 6 und
# c = -0,62 genau dieser Datensatz vor dem Runden (Steigung -0,11, R² 0,00).
#
# „1000 Stichproben“ zieht bei jedem Klick 1000 neue Stichproben mit neuen
# Sitzungszahlen und zeigt vier Kennwerte. Die 95-Prozent-Intervalle rechnen wie
# confint() mit dem t-Quantil. Solange die Kennwerte zu sehen sind, zieht auch
# jede Änderung von k 1000 neue Stichproben.
#
# Zu erwartende Werte
#   „1000 Stichproben“ (Erwartungswerte aus 40 000 Stichproben. Bei 1000
#   Stichproben schwankt der Anteil der Intervalle von Klick zu Klick mit einer
#   Standardabweichung von etwa 1,2 Prozentpunkten, die tatsächliche Streuung
#   um etwa 0,002)
#     k      Mittelwert  tatsächliche  Standardfehler  Anteil der Intervalle
#                        Streuung      im Mittel       mit 1,1
#     0      1,10        0,027         0,027           95 %
#     0,2    1,10        0,060         0,045           86 %
#     0,45   1,10        0,104         0,070           81 %
#     1      1,10        0,202         0,125           78 %
#   Reiter „Krümmung“: Die Gerade schätzt im Mittel die mittlere Steigung des
#   Prozesses zwischen Stufe 0 und 10, b + 10 * c, und nicht das
#   Regressionsgewicht b (PLAN_W03.md §6, MV03 Folie „Krümmung: Was das
#   Regressionsgewicht im linearen Modell schätzt“). Bei b = 6 im Mittel:
#     c        0      -0,3    -0,62   -1
#     Steigung 6,0    3,0     -0,2    -4,0
#   Die erste Stichprobe (Startwert von cafe) zeigt bei b = 6 die Steigungen
#   6,02, 3,05, -0,11 und -3,86 und R² 0,97, 0,85, 0,00 und 0,65. Block 4 des
#   Seminarskripts rundet die Daten und kommt auf fast dieselben Steigungen.

library(shiny)
library(ggplot2)

# --- Farben und Schrift (TECHNIK.md §4) ----------------------------------------

mv_farben <- c(papier = "#FFFFFF", tinte = "#121212", tinte2 = "#5A5A5A",
               violett = "#5B4B9E", orange = "#B7791F", akzent = "#35638A",
               grau1 = "#BDBDB8", grau2 = "#7A7A76", grau3 = "#3A3A38",
               toenung_o = "#F1E4C9", toenung_v = "#E4DFF1")

# IBM Plex Sans wird verwendet, wenn die Schrift auf dem Rechner installiert
# ist. Im Browser (webR) fehlt sie in der Regel. Dann bleibt der Name leer, und
# das Grafikgerät nimmt seine Standardschrift.
plex_installiert <- function() {
  ordner <- c("~/.fonts", "~/.local/share/fonts", "/usr/share/fonts",
              "/usr/local/share/fonts", "~/Library/Fonts", "/Library/Fonts",
              file.path(Sys.getenv("WINDIR"), "Fonts"),
              file.path(Sys.getenv("LOCALAPPDATA"), "Microsoft", "Windows", "Fonts"))
  treffer <- tryCatch({
    ordner <- ordner[nzchar(ordner) & dir.exists(ordner)]
    list.files(ordner, pattern = "^IBMPlexSans.*\\.(ttf|otf)$",
               recursive = TRUE, ignore.case = TRUE)
  }, error = function(e) character(0))
  length(treffer) > 0
}
schrift <- if (plex_installiert()) "IBM Plex Sans" else ""

# Unter Windows ohne ragg zeichnet Shiny mit dem Windows-Grafikgerät. Es findet
# eine installierte Schrift erst, wenn sie mit windowsFonts() angemeldet ist.
if (nzchar(schrift) && .Platform$OS.type == "windows") {
  anmeldung <- list(grDevices::windowsFont(schrift))
  names(anmeldung) <- schrift
  do.call(grDevices::windowsFonts, anmeldung)
}

# theme_mv() aus 20_Produktion/generator/theme_mv.R, mit der Schrift von oben
theme_mv <- function(base_size = 16) {
  theme_minimal(base_size = base_size, base_family = schrift) +
    theme(
      plot.background  = element_rect(fill = "#FFFFFF", colour = NA),
      panel.background = element_rect(fill = "#FFFFFF", colour = NA),
      panel.grid.minor = element_blank(),
      panel.grid.major = element_line(colour = "#D6D6D2", linewidth = 0.3),
      axis.text        = element_text(colour = "#5A5A5A"),
      axis.title       = element_text(colour = "#121212"),
      strip.text       = element_text(colour = "#121212", hjust = 0),
      legend.position  = "none"
    )
}

# Schriftgrößen in pt. Abbildungen unter 420 Pixeln Breite (Telefon)
# bekommen kleinere Schrift und weniger Achsenbeschriftungen, aber nie unter
# 12 pt.
darstellung <- function(breite_px = NULL) {
  schmal <- !is.null(breite_px) && breite_px < 420
  list(titel = if (schmal) 13 else 15,
       achse = if (schmal) 12 else 13,
       y_schritte = if (schmal) 5 else 7,
       schmal = schmal)
}
thema <- function(d) {
  theme_mv(d$titel) +
    theme(axis.text    = element_text(size = d$achse, colour = mv_farben[["tinte2"]]),
          axis.title   = element_text(size = d$titel, colour = mv_farben[["tinte"]]),
          axis.title.x = element_text(margin = margin(t = 6)),
          axis.title.y = element_text(margin = margin(r = 6)),
          plot.margin  = margin(6, 22, 4, 4))
}

# Linienstärken: wahre und geschätzte Linien etwa 2 pt, die Nulllinie etwa 1,5 pt
linie_dick <- 0.9
linie_null <- 0.7

# Punkte in Tinte sekundär mit dünnem Rand in Papierfarbe, damit sich
# überlappende Punkte trennen lassen (wie figs_w03.R)
punkte <- function(...) {
  geom_point(shape = 21, fill = mv_farben[["tinte2"]], colour = mv_farben[["papier"]],
             stroke = 0.3, size = 2.3, ...)
}

# Zahlen mit Dezimalkomma und typografischem Minus
zahl <- function(x, stellen = 2) {
  x <- round(x, stellen)
  x[x == 0] <- 0
  sub("^-", "\u2212", formatC(x, format = "f", digits = stellen, decimal.mark = ","))
}
prozent <- function(anteil) paste0(zahl(100 * anteil, 1), "\u00a0%")
# Reglerwerte ohne überflüssige Nullen, etwa 0, 0,45 und 1
reglerwert <- function(x) sub(",?0+$", "", zahl(x, 2))
# Achsenbeschriftung mit so wenigen Nachkommastellen wie nötig, für alle
# Beschriftungen einer Achse gleich (0, 5, 10 oder 2,5, 5,0, 7,5)
achse <- function(x) {
  werte <- x[is.finite(x)]
  stellen <- 0
  ungenau <- function(st) any(abs(round(werte, st) - werte) > 1e-9 * pmax(1, abs(werte)))
  while (stellen < 4 && ungenau(stellen)) {
    stellen <- stellen + 1
  }
  ifelse(is.finite(x), zahl(x, stellen), NA)
}

# --- Datengenerierende Prozesse und Schätzung -----------------------------------

n <- 250
startwert_streuung <- 204    # Startwert von therapie
startwert_kruemmung <- 2040  # Startwert von cafe

# Ungleiche Streuung: Sitzungszahlen und standardnormalverteilte Fehler. Die
# Reihenfolge der Züge ist dieselbe wie in gen_w03.R. Der Regler k rechnet
# dieselben Zufallszahlen um.
ziehe_streuung <- function() {
  therapy_sessions <- pmin(20, rnbinom(n, size = 2, mu = 6))
  list(therapy_sessions = therapy_sessions, z = rnorm(n))
}
symptom_drop <- function(therapy_sessions, z, k) {
  3 + 1.1 * therapy_sessions + (2 + k * therapy_sessions) * z
}

# Krümmung: Lautstärke und standardnormalverteilte Fehler, Reihenfolge wie in
# gen_w03.R
ziehe_kruemmung <- function() {
  noise_level <- runif(n, 0, 10)
  list(noise_level = noise_level, z = rnorm(n))
}
wahre_kurve <- function(noise_level, gewicht_b, kruemmung_c) {
  20 + gewicht_b * noise_level + kruemmung_c * noise_level^2
}

# Kleinste-Quadrate-Schätzung mit einem Prädiktor, für einen Vektor (eine
# Stichprobe) oder eine Matrix (eine Stichprobe pro Spalte). Die Werte stimmen
# mit lm(y ~ x), summary() und confint() überein.
schaetze <- function(x, y) {
  x <- as.matrix(x)
  y <- as.matrix(y)
  anzahl <- nrow(y)
  x_mittel <- colMeans(x)
  y_mittel <- colMeans(y)
  xz <- x - rep(x_mittel, each = anzahl)
  yz <- y - rep(y_mittel, each = anzahl)
  sxx <- colSums(xz * xz)
  sxy <- colSums(xz * yz)
  syy <- colSums(yz * yz)
  b1 <- sxy / sxx
  qs_residuen <- pmax(syy - b1 * sxy, 0)
  list(b0 = y_mittel - b1 * x_mittel, b1 = b1,
       se = sqrt(qs_residuen / (anzahl - 2) / sxx),
       r2 = 1 - qs_residuen / syy)
}

# 1000 Stichproben zur ungleichen Streuung in vier Blöcken zu je 250 Spalten.
# Jede Stichprobe zieht neue Sitzungszahlen aus derselben Verteilung, wie die
# Simulation in gen_w03.R. Die 95-Prozent-Intervalle rechnen wie confint() mit dem
# t-Quantil bei n - 2 Freiheitsgraden.
simuliere_streuung <- function(k, anzahl = 1000, block = 250) {
  b1 <- se <- numeric(0)
  for (i in seq_len(anzahl / block)) {
    sitzungen <- matrix(pmin(20, rnbinom(n * block, size = 2, mu = 6)), nrow = n)
    z <- matrix(rnorm(n * block), nrow = n)
    e <- schaetze(sitzungen, symptom_drop(sitzungen, z, k))
    b1 <- c(b1, e$b1)
    se <- c(se, e$se)
  }
  t_quantil <- qt(0.975, df = n - 2)
  list(k = k, mittel = mean(b1), streuung = sd(b1), se_mittel = mean(se),
       ueberdeckung = mean(b1 - t_quantil * se <= 1.1 & 1.1 <= b1 + t_quantil * se))
}

# --- Abbildungen ---------------------------------------------------------------

# Die ganzzahligen Sitzungszahlen werden im Streudiagramm leicht waagerecht
# gestreut (wie fig03_a_streuung). Der feste Startwert hält die Punkte an ihrem
# Platz, wenn der Regler bewegt wird.
streuen <- position_jitter(width = 0.2, height = 0, seed = 3)

abbildung_streuung <- function(daten, e, d = darstellung()) {
  ggplot(daten, aes(x = therapy_sessions, y = symptom_drop)) +
    punkte(position = streuen) +
    geom_abline(intercept = 3, slope = 1.1, colour = mv_farben[["violett"]],
                linewidth = linie_dick) +
    geom_abline(intercept = e$b0, slope = e$b1, colour = mv_farben[["orange"]],
                linewidth = linie_dick, linetype = "dashed") +
    scale_x_continuous(breaks = seq(0, 20, if (d$schmal) 10 else 5), labels = achse) +
    scale_y_continuous(labels = achse, n.breaks = d$y_schritte) +
    coord_cartesian(xlim = c(0, 20)) +
    labs(x = "Therapiesitzungen (Anzahl)", y = "Rückgang der Symptome (Punkte)") +
    thema(d)
}

abbildung_kruemmung <- function(daten, e, gewicht_b, kruemmung_c, d = darstellung()) {
  kurve <- data.frame(noise_level = seq(0, 10, by = 0.05))
  kurve$creativity <- wahre_kurve(kurve$noise_level, gewicht_b, kruemmung_c)
  ggplot(daten, aes(x = noise_level, y = creativity)) +
    punkte() +
    geom_line(data = kurve, colour = mv_farben[["violett"]], linewidth = linie_dick) +
    geom_abline(intercept = e$b0, slope = e$b1, colour = mv_farben[["orange"]],
                linewidth = linie_dick, linetype = "dashed") +
    scale_x_continuous(breaks = seq(0, 10, if (d$schmal) 2 else 1), labels = achse) +
    scale_y_continuous(labels = achse, n.breaks = d$y_schritte) +
    coord_cartesian(xlim = c(0, 10)) +
    labs(x = "Lautstärke (Stufe 0 bis 10)", y = "Kreativität (Punkte)") +
    thema(d)
}

# Residuen gegen vorhergesagte Werte, wie augment() |> ggplot() im Skript. Die
# y-Achse liegt symmetrisch um 0.
abbildung_residuen <- function(vorhergesagt, residuum, x_titel, d = darstellung()) {
  grenze <- max(abs(residuum)) * 1.05
  ggplot(data.frame(vorhergesagt, residuum), aes(x = vorhergesagt, y = residuum)) +
    geom_hline(yintercept = 0, colour = mv_farben[["tinte"]], linewidth = linie_null) +
    punkte() +
    scale_x_continuous(labels = achse, n.breaks = if (d$schmal) 5 else 6) +
    scale_y_continuous(labels = achse, n.breaks = d$y_schritte) +
    coord_cartesian(ylim = c(-grenze, grenze)) +
    labs(x = x_titel, y = "Residuum (Punkte)") +
    thema(d)
}

# --- Piktogramme der Variablen (STIL.md §2) -------------------------------------

