# Die Regler zeigen Zahlen mit Dezimalkomma und typografischem Minus. Die
# Beschriftungen unter den Reglern stehen in Schritten von 0,2 (k), 2,5 (b) und
# 0,5 (c).
js <- "
(function() {
  function deutsch(num) {
    var text = String(Math.round(num * 1000) / 1000).replace('.', ',');
    return text.charAt(0) === '-' ? '\\u2212' + text.slice(1) : text;
  }
  var gitter = { k: 5, b: 4, c: 4 };
  function anpassen(el) {
    var regler = $(el).data('ionRangeSlider');
    if (!regler || regler.options.prettify === deutsch) return;
    var neu = { prettify_enabled: true, prettify: deutsch };
    if (gitter[el.id]) neu.grid_num = gitter[el.id];
    regler.update(neu);
  }
  $(document).on('shiny:bound', function(e) {
    if ($(e.target).hasClass('js-range-slider')) anpassen(e.target);
  });
  $(document).on('shiny:connected', function() {
    $('.js-range-slider').each(function() { anpassen(this); });
  });
})();
"

# Schlüssel für das Streudiagramm: Linienstück und Text in der Farbe der Linie
linienstueck <- function(farbe, strich = NULL) {
  tags$svg(width = "30", height = "10", `aria-hidden` = "true",
           tag("line", list(x1 = "1", y1 = "5", x2 = "29", y2 = "5", stroke = farbe,
                            `stroke-width` = "2.5", `stroke-dasharray` = strich)))
}
schluessel <- function(wahr) {
  div(class = "schluessel",
      span(class = "eintrag wahr", linienstueck(mv_farben[["violett"]]), wahr),
      span(class = "eintrag geschaetzt", linienstueck(mv_farben[["orange"]], "7 5"),
           "geschätzte Gerade"))
}

# Zeile mit dem datengenerierenden Prozess. Wahre Werte stehen in {…} und werden
# violett. Variablen stehen als [schlüssel:Name] und bekommen ihr Piktogramm. Um
# das Gleichheitszeichen stehen geschützte Leerzeichen.
prozess <- function(text) {
  text <- gsub(" = ", "\u00a0=\u00a0", text, fixed = TRUE)
  text <- gsub("\\{([^}]*)\\}", "<span class=\"wahr\">\\1</span>", text)
  for (variable in names(pikto_svg)) {
    text <- gsub(paste0("\\[", variable, ":([^]]*)\\]"), pikto(variable, "\\1"), text)
  }
  p(class = "prozess", HTML(paste0("Datengenerierender Prozess: ", text)))
}

# Streudiagramm und Residuenplot nebeneinander, bei schmalem Fenster untereinander
abbildungen <- function(streu_id, resid_id, wahr) {
  div(class = "abbildungen",
      div(class = "kopf1", h3("Streudiagramm"), schluessel(wahr)),
      div(class = "abb1", plotOutput(streu_id, height = "360px")),
      div(class = "kopf2", h3("Residuenplot"),
          span(class = "hinweis", "Residuen gegen vorhergesagte Werte")),
      div(class = "abb2", plotOutput(resid_id, height = "360px")))
}

