# --- Server --------------------------------------------------------------------

server <- function(input, output, session) {

  # Erste Stichproben mit den Startwerten von therapie und cafe, danach ohne festen
  # Startwert
  set.seed(startwert_streuung)
  stichprobe_streuung <- reactiveVal(ziehe_streuung())
  set.seed(startwert_kruemmung)
  stichprobe_kruemmung <- reactiveVal(ziehe_kruemmung())
  set.seed(NULL)

  observeEvent(input$neu_streuung, stichprobe_streuung(ziehe_streuung()))
  observeEvent(input$neu_kruemmung, stichprobe_kruemmung(ziehe_kruemmung()))

  # Breite einer Abbildung im Browser, für darstellung()
  breite <- function(id) session$clientData[[paste0("output_", id, "_width")]]

  # Reiter „Ungleiche Streuung“, eine Stichprobe
  streuung <- reactive({
    req(input$k)
    s <- stichprobe_streuung()
    daten <- data.frame(therapy_sessions = s$therapy_sessions,
                        symptom_drop = symptom_drop(s$therapy_sessions, s$z, input$k))
    e <- schaetze(daten$therapy_sessions, daten$symptom_drop)
    daten$vorhergesagt <- e$b0 + e$b1 * daten$therapy_sessions
    daten$residuum <- daten$symptom_drop - daten$vorhergesagt
    list(daten = daten, e = e)
  })

  output$streu_streuung <- renderPlot(
    abbildung_streuung(streuung()$daten, streuung()$e,
                       darstellung(breite("streu_streuung"))),
    res = 96,
    alt = paste("Streudiagramm von Therapiesitzungen und Rückgang der Symptome",
                "mit wahrer und geschätzter Geraden"))
  output$resid_streuung <- renderPlot(
    abbildung_residuen(streuung()$daten$vorhergesagt, streuung()$daten$residuum,
                       "Vorhergesagter Rückgang (Punkte)",
                       darstellung(breite("resid_streuung"))),
    res = 96, alt = "Residuen gegen vorhergesagte Werte")
  output$kennwerte_streuung <- renderUI({
    e <- streuung()$e
    p(span(class = "geschaetzt", paste0("Geschätzte Steigung: ", zahl(e$b1))),
      paste0(" (Standardfehler ", zahl(e$se, 3), ")"))
  })

  # Reiter „Ungleiche Streuung“, 1000 Stichproben. Die Anzeige erscheint mit dem
  # ersten Klick. Jeder Klick zieht 1000 neue Stichproben, ebenso jede Änderung
  # von k, sobald der Regler 0,4 Sekunden stillsteht.
  k_ruhig <- debounce(reactive(input$k), 400)
  tausend <- reactive({
    req(input$tausend > 0)
    input$tausend
    req(k_ruhig())
    simuliere_streuung(k_ruhig())
  })

  output$kennwerte_tausend <- renderUI({
    t <- tausend()
    zeile <- function(text, wert) tags$tr(tags$td(text), tags$td(wert))
    div(class = "tausend",
        h3(paste0("1000 Stichproben mit k\u00a0=\u00a0", reglerwert(t$k))),
        p(class = "hinweis", "Wird neu berechnet, wenn Sie k ändern."),
        tags$table(
          class = "mv-tabelle",
          zeile("Mittelwert der Steigungen:", zahl(t$mittel)),
          zeile("Tatsächliche Streuung der Steigungen:", zahl(t$streuung, 3)),
          zeile("Ausgegebener Standardfehler im Mittel:", zahl(t$se_mittel, 3)),
          zeile(tagList("Anteil der 95-Prozent-Intervalle, die ",
                        span(class = "wahr", "1,1"), " enthalten:"),
                prozent(t$ueberdeckung))))
  })

  # Reiter „Krümmung“
  kruemmung <- reactive({
    req(!is.null(input$b), !is.null(input$c))
    s <- stichprobe_kruemmung()
    daten <- data.frame(noise_level = s$noise_level,
                        creativity = wahre_kurve(s$noise_level, input$b, input$c) + 3 * s$z)
    e <- schaetze(daten$noise_level, daten$creativity)
    daten$vorhergesagt <- e$b0 + e$b1 * daten$noise_level
    daten$residuum <- daten$creativity - daten$vorhergesagt
    list(daten = daten, e = e, gewicht_b = input$b, kruemmung_c = input$c)
  })

  output$streu_kruemmung <- renderPlot({
    k <- kruemmung()
    abbildung_kruemmung(k$daten, k$e, k$gewicht_b, k$kruemmung_c,
                        darstellung(breite("streu_kruemmung")))
  }, res = 96, alt = paste("Streudiagramm von Lautstärke und Kreativität mit wahrer",
                           "Kurve und geschätzter Geraden"))
  output$resid_kruemmung <- renderPlot(
    abbildung_residuen(kruemmung()$daten$vorhergesagt, kruemmung()$daten$residuum,
                       "Vorhergesagte Kreativität (Punkte)",
                       darstellung(breite("resid_kruemmung"))),
    res = 96, alt = "Residuen gegen vorhergesagte Werte")
  # Wahre Werte violett, die Schätzung orangefarben. Die mittlere Steigung des
  # Prozesses zwischen Stufe 0 und 10 ist (f(10) - f(0)) / 10 = b + 10 * c.
  output$kennwerte_kruemmung <- renderUI({
    k <- kruemmung()
    tagList(
      p(span(class = "wahr", paste0("Wahres Regressionsgewicht b: ", zahl(k$gewicht_b)))),
      p(span(class = "wahr", paste0("Mittlere Steigung des Prozesses von Stufe 0 bis 10: ",
                                    zahl(k$gewicht_b + 10 * k$kruemmung_c)))),
      p(span(class = "geschaetzt", paste0("Geschätzte Steigung: ", zahl(k$e$b1))),
        paste0(" (R²: ", zahl(k$e$r2), ")")))
  })
}

